'use strict';
// Pure policy shared by the staged workflow snippets and the isolated test harness.
// No API calls, writes, credentials, Slack sends, or research calls occur here.
const F = Object.freeze({
  cycle:'Replenishment Cycle ID', baseline:'Replenishment Starting Queue',
  receipt:'Replenishment Receipt', progress:'Replenishment Cycle Progress',
  claim:'Replenishment Alert Claim', delivery:'Replenishment Alert Delivery',
  ready:'Replenishment Alert Ready'
});
function integer(value, name, min=0) {
  if(value===null || value===undefined || value==='' || typeof value==='boolean') throw Error(name+' is missing.');
  const n=Number(value); if(!Number.isSafeInteger(n)||n<min)throw Error(name+' is invalid.');return n;
}
function timestamp(value,name){const t=Date.parse(value);if(!Number.isFinite(t))throw Error(name+' is invalid.');return t;}
function cycleId(campaignId,importId){return 'bison:'+integer(campaignId,'campaign ID',1)+':import:'+integer(importId,'import ID',1);}
function eventKey(recordId,cycle){if(!/^rec[a-zA-Z0-9]{14}$/.test(recordId))throw Error('Invalid campaign record ID.');if(cycle!=='initial'&&!/^bison:\d+:import:\d+$/.test(cycle))throw Error('Invalid cycle ID.');return recordId+'|progress_60'+(cycle==='initial'?'':'|'+cycle);}
function progress(fields){
  if(!fields[F.cycle]){const p=Number(fields.Progress);return Number.isFinite(p)?Math.max(0,Math.min(1,p)):null;}
  const q=integer(fields[F.baseline],'starting queue',1),remaining=integer(fields['Total Leads Remaining'],'remaining queue');
  // An increase can be an untracked import/counter correction. Never manufacture consumption.
  if(remaining>q)return null;
  return Math.max(0,Math.min(1,1-remaining/q));
}
function makeCheckpoint(input, existingFields={}){
  const {recordId,receipt,snapshot,importCreatedAt,observedAt}=input;
  const c=integer(receipt.campaignId,'campaign ID',1),i=integer(receipt.leadListId,'import ID',1);
  const id=cycleId(c,i);eventKey(recordId,id);
  if(receipt.error||integer(receipt.failed||0,'failed rows')!==0||integer(receipt.added,'net added',0)===0)return null;
  if(receipt.attachmentReceipt?.success!==true||receipt.attachmentReceipt.campaignId!==c||receipt.attachmentReceipt.leadListId!==i)throw Error('Exact attachment acknowledgment missing.');
  if(receipt.providerImport?.status!=='Processed'||integer(receipt.providerImport.id,'confirmed import',1)!==i)throw Error('Import is not confirmed processed.');
  const oldCycle=String(existingFields[F.cycle]||'');
  if(oldCycle===id)return null; // Never reset a baseline on a duplicate receipt.
  const created=timestamp(importCreatedAt,'import creation time');timestamp(observedAt,'observation time');
  if(oldCycle){
    let old;try{old=JSON.parse(existingFields[F.receipt]||'');}catch{throw Error('Existing cycle receipt is missing or invalid.');}
    if(old.cycleId!==oldCycle)throw Error('Existing receipt identity mismatch.');
    const oldTime=timestamp(old.importCreatedAt,'previous import creation time');
    if(created<=oldTime)throw Error('Old or ambiguously ordered import cannot replace the current cycle.');
  }
  if(integer(snapshot.id,'snapshot campaign',1)!==c)throw Error('Provider campaign identity mismatch.');
  const total=integer(snapshot.total_leads,'total leads'),contacted=integer(snapshot.total_leads_contacted,'contacted leads');
  if(contacted>total||total!==integer(receipt.afterTotal,'confirmed total'))throw Error('Post-import snapshot is inconsistent; reconcile the existing import, do not upload again.');
  const queue=total-contacted;
  if(queue===0)throw Error('Post-import uncontacted queue is zero; reconcile before initializing a fresh cycle.');
  const record={schemaVersion:1,cycleId:id,campaignId:c,importId:i,importCreatedAt,observedAt,sourceLeadListId:input.sourceLeadListId,outputType:receipt.outputType,netAdded:receipt.added,startingQueue:queue,totalLeads:total,contactedLeads:contacted,metric:'uncontacted campaign queue after confirmed replenishment; includes older unsent leads'};
  return {recordId,fields:{[F.cycle]:id,[F.baseline]:queue,[F.receipt]:JSON.stringify(record),'Total Leads':total,'Total Leads Contacted':contacted,'Total Leads Remaining':queue}};
}
function planAlert({recordId,triggerCycleId,fields,taskKeys=[]}){
  const current=String(fields[F.cycle]||'initial');
  if(String(triggerCycleId||'initial')!==current)return {send:false,reason:'stale event'};
  const key=eventKey(recordId,current),p=progress(fields);
  if(p===null||p<0.6)return {send:false,reason:'not eligible'};
  if(fields[F.claim]===current||taskKeys.includes(key))return {send:false,reason:'already claimed; reconcile pending delivery instead of replaying'};
  if(current==='initial'&&taskKeys.some(k=>[recordId+'|learning_60percent',recordId+'|forecast_60percent'].includes(k)))return {send:false,reason:'legacy checkpoint already handled'};
  return {send:true,cycleId:current,key,progress:p,remaining:integer(fields['Total Leads Remaining']??0,'remaining queue')};
}
function validateEvent({recordId,cycleId:expected,fields}){
  const current=String(fields[F.cycle]||'initial');eventKey(recordId,expected);
  if(expected!==current)throw Error('Stale replenishment event: campaign cycle changed.');
  const p=progress(fields);if(p===null||p<0.6)throw Error('Cycle is not at the replenishment threshold.');
  return {cycleId:current,cycleProgress:p,eventKey:eventKey(recordId,current)};
}
function learningIdentity(campaignId,cycle,completion){
  const checkpoint=cycle==='initial'?(completion>=0.999?'completed':'60percent'):'60percent';
  return {checkpoint,marker:cycle==='initial'?`[Campaign learning v1:${campaignId}:${checkpoint}]`:`[Campaign learning v2:${campaignId}:${checkpoint}:${cycle}]`,suffix:cycle==='initial'?'':`|${cycle}`};
}

'use strict';
// Pure coordinator state machine. SQL/native HTTP nodes perform all effects.


const AT='https://api.airtable.com/v0/appxqINt5XKw7a76A/';
const CAM=AT+'tblAVAA6uBPaMj28P/',TASK=AT+'tblRBxm2N53331mIm';
const PREFIX='replenishment:v2:';
const policyCycleId=(campaignId,importId)=>'bison:'+integer(campaignId,'receipt campaign',1)+':import:'+integer(importId,'receipt import',1);
const clone=x=>JSON.parse(JSON.stringify(x));
function normalize(input,executionId,internal=false){
 const b=input.body??input;const recordId=String(b.recordId||'');
 if(!/^rec[a-zA-Z0-9]{14}$/.test(recordId))throw Error('Invalid campaign record ID.');
 const kind=internal?String(b.operation||'checkpoint'):String(b.operation||'');
 if(!(internal?['checkpoint','commit_review','commit_forecast']:['claim','complete']).includes(kind))throw Error('Unsupported coordinator operation.');
 const cycle=kind==='checkpoint'&&b.receipt?policyCycleId(b.receipt.campaignId,b.receipt.leadListId):String(b.cycleId||'initial');eventKey(recordId,cycle);
 if(!internal&&!/^[a-f0-9-]{36}$/i.test(String(b.attemptId||'')))throw Error('An exact delivery attempt ID is required.');
 if(kind==='complete'&&!/^\d+$/.test(String(b.claimExecutionId||'')))throw Error('Exact claim execution ID required.');
 const attempt=internal?String(executionId)+':'+kind:b.attemptId;
 return {stage:'start',kind,internal,recordId,cycleId:cycle,attemptId:attempt,executionId:String(executionId),claimExecutionId:kind==='complete'?String(b.claimExecutionId):String(executionId),resource:PREFIX+'campaign:'+recordId,ownerRequest:PREFIX+'owner:'+recordId+':'+attempt,eventDbKey:PREFIX+'event:'+eventKey(recordId,cycle),eventKey:eventKey(recordId,cycle),commit:kind.startsWith('commit_')?clone(b):null,checkpoint:kind==='checkpoint'?{recordId,receipt:b.receipt,sourceLeadListId:b.sourceLeadListId}:null,startedAt:new Date().toISOString(),waitCount:0,lockOwned:false};
}
function responseData(response){
 if(!response||response.error)throw Error('The preceding operation did not confirm success.');
 if(response.statusCode!=null&&(Number(response.statusCode)<200||Number(response.statusCode)>=300))throw Error('Operation failed with HTTP '+response.statusCode+'.');
 const b=response.body??response;return typeof b==='string'?JSON.parse(b):b;
}
function result(state,response,action,extra={}){return {state,action,...extra};}
function finish(s,payload,code=200){return result(s,null,s.internal?'done':'respond',{payload:{recordId:s.recordId,cycleId:s.newCycleId||s.cycleId,...payload},httpStatus:code});}
function at(s,stage,method,url,body){s.stage=stage;return result(s,null,'airtable',{request:{method,url,...(body?{body}:{} )}});}
function bison(s,stage,path){s.stage=stage;return result(s,null,'bison',{request:{method:'GET',url:'https://send.dulcy.io'+path,apiKey:s.apiKey}});}
function pg(s,stage,op,params){s.stage=stage;return result(s,null,op,{params});}
function record(s,r){if(r.id!==s.recordId)throw Error('Campaign identity mismatch.');s.fields=r.fields||{};return s.fields;}
function providerContext(s){
 const f=s.fields;s.campaignId=integer(f.ID||f['EmailBison Direct Campaign ID'],'campaign ID',1);
 const key=f['EmailBison API (from Client)'];s.apiKey=Array.isArray(key)?key[0]:key;
 if(!s.apiKey)throw Error('Existing EmailBison credential lookup unavailable.');
}
function release(s,after,payload){s.afterRelease=after;s.finishPayload=payload;return pg(s,'released','pg_release',[s.resource,s.ownerRequest,s.claimExecutionId]);}
function events(r){return Object.fromEntries((r.events||[]).map(e=>[e.request_id,e.context]));}
function insert(s,stage,key,context){return pg(s,stage,'pg_insert',[s.resource,s.ownerRequest,s.claimExecutionId,key,JSON.stringify(context)]);}
function existingTasksUrl(s){
 const keys=[s.eventKey];if(s.cycleId==='initial')keys.push(s.recordId+'|learning_60percent',s.recordId+'|forecast_60percent');
 const formula='OR('+keys.map(k=>'{Automation Key}='+JSON.stringify(k)).join(',')+')';
 return TASK+'?pageSize=100&filterByFormula='+encodeURIComponent(formula);
}
function delivery(s,downstream){return {schemaVersion:2,cycleId:s.cycleId,eventKey:s.eventKey,taskId:s.taskId,status:'sent',sentAt:s.sentAt,downstream,claimExecutionId:s.claimExecutionId,attemptId:s.attemptId};}
function failure(s,error){
 const message=String(error.message||error).replace(s.apiKey||'__no_key__','[REDACTED]').slice(0,600);
 return finish(s,{ok:false,blocked:true,retainedLock:s.lockOwned||s.stage==='acquired',lockOutcome:s.lockOwned?'held':(s.stage==='acquired'?'uncertain':'not_owned'),recordId:s.recordId,cycleId:s.cycleId,reason:message,instruction:'Reconcile this exact operation. Do not reupload leads or blindly resend Slack.'},503);
}
function plan(input){
 const s=clone(input.state);let r;
 try{
  if(s.stage!=='start')r=responseData(input.response);
  // SQL transport success alone does not establish lock ownership or audit persistence.
  const insertStages=['event_claimed','claim_task_audited','commit_claimed','commit_finished','completion_claimed','sent_audited','downstream_claimed','checkpoint_audited'];
  if(insertStages.includes(s.stage)){
   if(r.owned!==true)throw Error('Audit operation did not confirm exact mutex ownership. Reconcile before further effects.');
   if(typeof r.inserted!=='boolean')throw Error('Audit insertion outcome is uncertain. Reconcile before further effects.');
  }
  if(['commit_finished','checkpoint_audited','claim_task_audited','sent_audited','downstream_audited'].includes(s.stage)&&r.inserted!==true)throw Error('New confirmation receipt was not inserted. Reconcile the existing receipt; do not repeat external effects.');
  if(s.stage==='commit_existing'&&r.owned!==true)throw Error('Existing commit inspection did not confirm exact mutex ownership. Reconcile before further effects.');
  switch(s.stage){
   case 'start':
    if(s.kind==='complete')return pg(s,'completion_owned','pg_read',[s.resource,s.ownerRequest,s.claimExecutionId,s.eventDbKey]);
    return pg(s,'acquired','pg_acquire',[s.resource,s.ownerRequest,s.claimExecutionId,JSON.stringify({purpose:'replenishment-'+s.kind,recordId:s.recordId,attemptId:s.attemptId})]);
   case 'acquired':
    if(!r.acquired){
     if(s.kind==='claim'){if(r.busy&&!r.already_used){s.stage='claim_busy_waited';return result(s,null,'wait');}return finish(s,{ok:true,shouldSend:false,busy:!!r.busy,alreadyUsed:!!r.already_used});}
     if(r.already_used)throw Error('This mutex owner already ran; reconcile the prior checkpoint instead of reentering it.');
     if(++s.waitCount>120)throw Error('Campaign mutex remains busy. Reconcile its existing owner; no expiry takeover was attempted.');
     s.ownerRequest=PREFIX+'owner:'+s.recordId+':'+s.attemptId+':retry:'+s.waitCount;s.stage='waited';return result(s,null,'wait');
    }
    s.lockOwned=true;return at(s,'campaign_read','GET',CAM+s.recordId);
   case 'claim_busy_waited':return finish(s,{ok:true,shouldSend:false,busy:true,reason:'campaign mutex busy; this owner was consumed'});
   case 'waited':return pg(s,'acquired','pg_acquire',[s.resource,s.ownerRequest,s.claimExecutionId,JSON.stringify({purpose:'replenishment-'+s.kind,recordId:s.recordId,attemptId:s.attemptId})]);
   case 'campaign_read':{
    const f=record(s,r);
    if(s.kind.startsWith('commit_')){
     if(String(f[F.cycle]||'initial')!==s.cycleId)return release(s,'finish',{ok:true,committed:false,reason:'stale cycle'});
     s.apiKey=undefined;
     s.campaignId=integer(f.ID||f['EmailBison Direct Campaign ID'],'campaign ID',1);
     const checkpoint=s.commit.checkpoint||'60percent';if(!['60percent','completed'].includes(checkpoint)||(s.cycleId!=='initial'&&checkpoint!=='60percent'))throw Error('Invalid original review checkpoint.');
     const identity=learningIdentity(s.campaignId,s.cycleId,checkpoint==='completed'?1:.6);
     s.commitKey=s.kind==='commit_review'?s.recordId+'|learning_'+identity.checkpoint+identity.suffix:s.eventKey;
     if(s.kind==='commit_review'&&(typeof s.commit.report!=='string'||s.commit.report.length<200||!s.commit.report.includes(identity.marker)))throw Error('Review identity or content is invalid.');
     if(s.kind==='commit_forecast'&&!/^\d{4}-\d{2}-\d{2}$/.test(String(s.commit.dueDate||'')))throw Error('Valid replenishment due date required.');
     return insert(s,'commit_claimed',s.eventDbKey+':'+s.kind,{purpose:s.kind+'-attempt-reserved',recordId:s.recordId,cycleId:s.cycleId,ownerRequest:s.ownerRequest});
    }
    providerContext(s);
    if(s.kind==='claim'){
     const current=String(f[F.cycle]||'initial');
     if(current!==s.cycleId)return release(s,'finish',{ok:true,shouldSend:false,reason:'stale cycle'});
     if(f[F.claim]===s.cycleId)return release(s,'finish',{ok:true,shouldSend:false,reason:'already claimed'});
     if(s.cycleId!=='initial'&&!s.cycleId.startsWith('bison:'+s.campaignId+':'))throw Error('Cycle provider identity mismatch.');
     return bison(s,'claim_stats','/api/campaigns/'+s.campaignId);
    }
    const receipt=s.checkpoint.receipt;
    if(!receipt||integer(receipt.campaignId,'receipt campaign',1)!==s.campaignId)throw Error('Checkpoint campaign identity mismatch.');
    if(receipt.error||Number(receipt.failed||0)>0||Number(receipt.added||0)<=0)return release(s,'finish',{ok:true,checkpoint:false,reason:'no confirmed positive successful growth'});
    return bison(s,'checkpoint_import','/api/lead-lists/'+integer(receipt.leadListId,'import ID',1));
   }
   case 'commit_claimed':
    if(!r.inserted)return pg(s,'commit_existing','pg_read',[s.resource,s.ownerRequest,s.claimExecutionId,s.eventDbKey]);
    return at(s,'commit_task_read','GET',TASK+'?pageSize=100&filterByFormula='+encodeURIComponent('{Automation Key}='+JSON.stringify(s.commitKey)));
   case 'commit_existing':{
    const e=events(r);if(e[s.eventDbKey+':'+s.kind+':done'])return release(s,'finish',{ok:true,committed:false,reason:'already committed'});
    return release(s,'finish',{ok:false,blocked:true,reason:'Previous commit reserved but completion is uncertain. Reconcile exact cycle; do not repeat writes.'});
   }
   case 'commit_task_read':{
    if(r.offset||!Array.isArray(r.records)||r.records.length>1)throw Error('Cannot safely resolve one cycle task.');
    const existing=r.records[0], f=s.fields, client=f.Client||[];
    let fields;
    if(s.kind==='commit_review'){
     // Existing owner status is never reset. Review content is updated only for this exact cycle.
     fields={'Automation Key':s.commitKey,'Task Name':String(f.Name||s.recordId)+' - 60% review',Client:client,Campaign:[s.recordId],Stage:'Review/QA',Priority:'High',Notes:s.commit.report,...(!existing?{Status:'Not Started'}:{})};
    }else{
     if(!existing)throw Error('Forecast cannot create a second alert task; the claimed cycle ledger is missing.');
     fields={'Due Date':s.commit.dueDate,...(s.commit.taskName?{'Task Name':String(s.commit.taskName).slice(0,300)}:{})};
    }
    s.commitTaskId=existing?.id;
    return at(s,'commit_task_saved',existing?'PATCH':'POST',TASK+(existing?'/'+existing.id:''),{fields});
   }
   case 'commit_task_saved':
    if(!/^rec[a-zA-Z0-9]{14}$/.test(String(r.id||''))||(s.commitTaskId&&r.id!==s.commitTaskId))throw Error('Cycle task write was not confirmed.');
    if(s.kind==='commit_review')return at(s,'commit_campaign_saved','PATCH',CAM+s.recordId,{fields:{'Improvement Sugestion':s.commit.report}});
    return insert(s,'commit_finished',s.eventDbKey+':'+s.kind+':done',{purpose:s.kind+'-write-confirmed',recordId:s.recordId,cycleId:s.cycleId,completedAt:new Date().toISOString()});
   case 'commit_campaign_saved':
    record(s,r);if(s.fields['Improvement Sugestion']!==s.commit.report)throw Error('Cycle review write not confirmed.');
    return insert(s,'commit_finished',s.eventDbKey+':'+s.kind+':done',{purpose:s.kind+'-write-confirmed',recordId:s.recordId,cycleId:s.cycleId,completedAt:new Date().toISOString()});
   case 'commit_finished':return release(s,'finish',{ok:true,committed:true,operation:s.kind,cycleId:s.cycleId});
   case 'checkpoint_import':{
    const v=r.data,receipt=s.checkpoint.receipt;
    if(!v||Number(v.id)!==Number(receipt.leadListId)||v.status!=='Processed'||Number(v.leads_failed)!==0||Number(v.leads_succeeded)!==Number(receipt.providerImport?.succeeded)||Number(v.leads_processed)!==Number(receipt.providerImport?.processed))throw Error('Existing processed import no longer matches the successful receipt.');
    s.importCreatedAt=v.created_at;return bison(s,'checkpoint_stats','/api/campaigns/'+s.campaignId);
   }
   case 'checkpoint_stats':{
    let cp;
    try{cp=makeCheckpoint({...s.checkpoint,snapshot:r.data,importCreatedAt:s.importCreatedAt,observedAt:new Date().toISOString()},s.fields);}
    catch(e){s.checkpointError=String(e.message).slice(0,500);return at(s,'checkpoint_error_saved','PATCH',CAM+s.recordId,{fields:{'Replenishment Checkpoint Error':'Import '+s.checkpoint.receipt.leadListId+' is processed. Alert checkpoint not initialized: '+s.checkpointError+'. Reconcile this existing import; do not reupload.'}});}
    if(!cp)return release(s,'finish',{ok:true,checkpoint:false,reason:'same import already checkpointed'});
    cp.fields['Replenishment Checkpoint Error']='';s.newCycleId=cp.fields[F.cycle];return at(s,'checkpoint_saved','PATCH',CAM+s.recordId,{fields:cp.fields});
   }
   case 'checkpoint_saved':
    record(s,r);if(s.fields[F.cycle]!==s.newCycleId)throw Error('Checkpoint write was not confirmed.');
    return insert(s,'checkpoint_audited',PREFIX+'checkpoint:'+s.recordId+':'+s.newCycleId,{purpose:'replenishment-checkpoint',recordId:s.recordId,cycleId:s.newCycleId,receipt:JSON.parse(s.fields[F.receipt])});
   case 'checkpoint_audited':return release(s,'finish',{ok:true,checkpoint:true,cycleId:s.newCycleId});
   case 'checkpoint_error_saved':record(s,r);return release(s,'finish',{ok:false,blocked:true,checkpoint:false,reason:s.checkpointError,instruction:'Existing import is complete. Reconcile only this branch checkpoint; do not reupload.'});
   case 'claim_stats':{
    const c=r.data;if(!c||integer(c.id,'provider campaign',1)!==s.campaignId)throw Error('Provider identity mismatch.');
    const total=integer(c.total_leads,'total leads'),contacted=integer(c.total_leads_contacted,'contacted leads');if(contacted>total)throw Error('Provider contacted count exceeds total.');
    s.remaining=total-contacted;
    const fresh={...s.fields,'Total Leads Remaining':s.remaining,Progress:Number(c.completion_percentage)/100};
    s.cycleProgress=progress(fresh);
    if(s.cycleProgress===null||s.cycleProgress<.6)return release(s,'finish',{ok:true,shouldSend:false,reason:'fresh provider queue is not at threshold'});
    s.qualifiedAt=new Date().toISOString();return at(s,'claim_tasks','GET',existingTasksUrl(s));
   }
   case 'claim_tasks':{
    if(r.offset||!Array.isArray(r.records))throw Error('Incomplete task reconciliation.');
    if(r.records.length)return release(s,'finish',{ok:true,shouldSend:false,reason:'existing cycle or legacy task'});
    const claim={purpose:'replenishment-alert-claim',recordId:s.recordId,cycleId:s.cycleId,eventKey:s.eventKey,attemptId:s.attemptId,claimExecutionId:s.claimExecutionId,ownerRequest:s.ownerRequest,qualifiedAt:s.qualifiedAt,cycleProgress:s.cycleProgress,remaining:s.remaining};
    return insert(s,'event_claimed',s.eventDbKey,claim);
   }
   case 'event_claimed':
    if(!r.inserted)return release(s,'finish',{ok:true,shouldSend:false,reason:'durable event claim already exists'});
    return at(s,'claim_task_saved','POST',TASK,{fields:{'Task Name':'Replenishment alert - '+String(s.fields.Name||s.recordId),'Automation Key':s.eventKey,Campaign:[s.recordId],Client:s.fields.Client||[],Status:'Blocked',Priority:'High',Stage:'Intake',Notes:'PENDING ALERT DELIVERY. '+s.eventKey+'\nClaimed '+s.qualifiedAt+'. Do not resend until Slack is reconciled. Cycle metric is the replenished uncontacted queue, including older unsent leads.'}});
   case 'claim_task_saved':
    if(!/^rec[a-zA-Z0-9]{14}$/.test(String(r.id||''))||r.fields?.['Automation Key']!==s.eventKey)throw Error('Alert task creation was not confirmed.');s.taskId=r.id;
    return insert(s,'claim_task_audited',s.eventDbKey+':task',{taskId:s.taskId,recordId:s.recordId,cycleId:s.cycleId,attemptId:s.attemptId});
   case 'claim_task_audited':
    return at(s,'claim_mirrored','PATCH',CAM+s.recordId,{fields:{[F.claim]:s.cycleId,[F.delivery]:JSON.stringify({schemaVersion:2,status:'pending',cycleId:s.cycleId,eventKey:s.eventKey,taskId:s.taskId,claimedAt:s.qualifiedAt,attemptId:s.attemptId,claimExecutionId:s.claimExecutionId})}});
   case 'claim_mirrored':{
    record(s,r);if(s.fields[F.claim]!==s.cycleId)throw Error('Alert claim mirror not confirmed.');
    const label=s.cycleId==='initial'?'campaign completion':'replenished uncontacted queue consumed';
    const alertText='The campaign *'+String(s.fields.Name||s.recordId)+'* has reached *'+(s.cycleProgress*100).toFixed(1)+'% '+label+'*.\n\nTime to add more leads or schedule a new campaign.\nUncontacted leads remaining: '+s.remaining+'.\nReplenishment cycle: '+s.cycleId+'\nEvent key: '+s.eventKey+'\nChecked: '+s.qualifiedAt+'\nThis is an early replenishment warning, not the date of the final follow-up.\n\n<!channel>';
    // Persistently hold the mutex across the original Airtable Slack action.
    // There is no lease expiry or automatic takeover. Only its exact completion may release it.
    return finish(s,{ok:true,shouldSend:true,cycleId:s.cycleId,eventKey:s.eventKey,taskId:s.taskId,attemptId:s.attemptId,claimExecutionId:s.claimExecutionId,alertText});
   }
   case 'completion_owned':{
    const e=events(r),claim=e[s.eventDbKey],sent=e[s.eventDbKey+':sent'];
    if(!claim||claim.attemptId!==s.attemptId||claim.claimExecutionId!==s.claimExecutionId)throw Error('Completion does not match the durable alert claim.');
    if(!r.owned){if(sent)return finish(s,{ok:true,alreadyComplete:true,slackSent:true});throw Error('Alert mutex ownership is not confirmed.');}
    s.lockOwned=true;s.taskId=e[s.eventDbKey+':task']?.taskId;if(!s.taskId)throw Error('Claimed task identity is missing.');
    s.sentAt=sent?.sentAt||new Date().toISOString();
    return insert(s,'completion_claimed',s.eventDbKey+':completion',{purpose:'exclusive-completion-handler',executionId:s.executionId,attemptId:s.attemptId,claimExecutionId:s.claimExecutionId});
   }
