    s.importCreatedAt=v.created_at;return bison(s,'checkpoint_stats','/api/campaigns/'+s.campaignId);
   }
   case 'checkpoint_stats':{
    let cp;
    try{cp=makeCheckpoint({...s.checkpoint,snapshot:r.data,importCreatedAt:s.importCreatedAt,observedAt:new Date().toISOString()},s.fields);}
    catch(e){s.checkpointError=String(e.message).slice(0,500);return at(s,'checkpoint_error_saved','PATCH',CAM+s.recordId,{fields:{'Replenishment Checkpoint Error':'Import '+s.checkpoint.receipt.leadListId+' is processed. Alert checkpoint not initialized: '+s.checkpointError+'. Reconcile this existing import; do not reupload.'}});}
    if(!cp)return release(s,'finish',{ok:true,checkpoint:false,reason:'same import already checkpointed'});
    cp.fields['Replenishment Checkpoint Error']='';s.newCycleId=cp.fields[F.cycle];return at(s,'checkpoint_saved','PATCH',CAM+s.recordId,{fields:cp.fields});
   }
   case 'checkpoint_saved':
    record(s,r);if(s.fields[F.cycle]!==s.newCycleId)throw Error('Checkpoint write was not confirmed.');
    return insert(s,'checkpoint_audited',PREFIX+'checkpoint:'+s.recordId+':'+s.newCycleId,{purpose:'replenishment-checkpoint',recordId:s.recordId,cycleId:s.newCycleId,receipt:JSON.parse(s.fields[F.receipt])});
   case 'checkpoint_audited':return release(s,'finish',{ok:true,checkpoint:true,cycleId:s.newCycleId});
   case 'checkpoint_error_saved':record(s,r);return release(s,'finish',{ok:false,blocked:true,checkpoint:false,reason:s.checkpointError,instruction:'Existing import is complete. Reconcile only this branch checkpoint; do not reupload.'});
   case 'claim_stats':{
    const c=r.data;if(!c||integer(c.id,'provider campaign',1)!==s.campaignId)throw Error('Provider identity mismatch.');
    const total=integer(c.total_leads,'total leads'),contacted=integer(c.total_leads_contacted,'contacted leads');if(contacted>total)throw Error('Provider contacted count exceeds total.');
    s.remaining=total-contacted;
    const fresh={...s.fields,'Total Leads Remaining':s.remaining,Progress:Number(c.completion_percentage)/100};
    s.cycleProgress=progress(fresh);
    if(s.cycleProgress===null||s.cycleProgress<.6)return release(s,'finish',{ok:true,shouldSend:false,reason:'fresh provider queue is not at threshold'});
    s.qualifiedAt=new Date().toISOString();return at(s,'claim_tasks','GET',existingTasksUrl(s));
   }
   case 'claim_tasks':{
    if(r.offset||!Array.isArray(r.records))throw Error('Incomplete task reconciliation.');
    if(r.records.length)return release(s,'finish',{ok:true,shouldSend:false,reason:'existing cycle or legacy task'});
    const claim={purpose:'replenishment-alert-claim',recordId:s.recordId,cycleId:s.cycleId,eventKey:s.eventKey,attemptId:s.attemptId,claimExecutionId:s.claimExecutionId,ownerRequest:s.ownerRequest,qualifiedAt:s.qualifiedAt,cycleProgress:s.cycleProgress,remaining:s.remaining};
    return insert(s,'event_claimed',s.eventDbKey,claim);
   }
   case 'event_claimed':
    if(!r.inserted)return release(s,'finish',{ok:true,shouldSend:false,reason:'durable event claim already exists'});
    return at(s,'claim_task_saved','POST',TASK,{fields:{'Task Name':'Replenishment alert - '+String(s.fields.Name||s.recordId),'Automation Key':s.eventKey,Campaign:[s.recordId],Client:s.fields.Client||[],Status:'Blocked',Priority:'High',Stage:'Intake',Notes:'PENDING ALERT DELIVERY. '+s.eventKey+'\nClaimed '+s.qualifiedAt+'. Do not resend until Slack is reconciled. Cycle metric is the replenished uncontacted queue, including older unsent leads.'}});
   case 'claim_task_saved':
    if(!/^rec[a-zA-Z0-9]{14}$/.test(String(r.id||''))||r.fields?.['Automation Key']!==s.eventKey)throw Error('Alert task creation was not confirmed.');s.taskId=r.id;
    return insert(s,'claim_task_audited',s.eventDbKey+':task',{taskId:s.taskId,recordId:s.recordId,cycleId:s.cycleId,attemptId:s.attemptId});
   case 'claim_task_audited':
    return at(s,'claim_mirrored','PATCH',CAM+s.recordId,{fields:{[F.claim]:s.cycleId,[F.delivery]:JSON.stringify({schemaVersion:2,status:'pending',cycleId:s.cycleId,eventKey:s.eventKey,taskId:s.taskId,claimedAt:s.qualifiedAt,attemptId:s.attemptId,claimExecutionId:s.claimExecutionId})}});
   case 'claim_mirrored':{
    record(s,r);if(s.fields[F.claim]!==s.cycleId)throw Error('Alert claim mirror not confirmed.');
    const label=s.cycleId==='initial'?'campaign completion':'replenished uncontacted queue consumed';
    const alertText='The campaign *'+String(s.fields.Name||s.recordId)+'* has reached *'+(s.cycleProgress*100).toFixed(1)+'% '+label+'*.\n\nTime to add more leads or schedule a new campaign.\nUncontacted leads remaining: '+s.remaining+'.\nReplenishment cycle: '+s.cycleId+'\nEvent key: '+s.eventKey+'\nChecked: '+s.qualifiedAt+'\nThis is an early replenishment warning, not the date of the final follow-up.\n\n<!channel>';
    // Persistently hold the mutex across the original Airtable Slack action.
    // There is no lease expiry or automatic takeover. Only its exact completion may release it.
    return finish(s,{ok:true,shouldSend:true,cycleId:s.cycleId,eventKey:s.eventKey,taskId:s.taskId,attemptId:s.attemptId,claimExecutionId:s.claimExecutionId,alertText});
   }
   case 'completion_owned':{
    const e=events(r),claim=e[s.eventDbKey],sent=e[s.eventDbKey+':sent'];
    if(!claim||claim.attemptId!==s.attemptId||claim.claimExecutionId!==s.claimExecutionId)throw Error('Completion does not match the durable alert claim.');
    if(!r.owned){if(sent)return finish(s,{ok:true,alreadyComplete:true,slackSent:true});throw Error('Alert mutex ownership is not confirmed.');}
    s.lockOwned=true;s.taskId=e[s.eventDbKey+':task']?.taskId;if(!s.taskId)throw Error('Claimed task identity is missing.');
    s.sentAt=sent?.sentAt||new Date().toISOString();
    return insert(s,'completion_claimed',s.eventDbKey+':completion',{purpose:'exclusive-completion-handler',executionId:s.executionId,attemptId:s.attemptId,claimExecutionId:s.claimExecutionId});
   }
   case 'completion_claimed':
    if(!r.inserted)return finish(s,{ok:true,alreadyProcessing:true,slackSent:true,instruction:'An existing completion owns this receipt. Do not resend Slack or release its mutex.'});
    return insert(s,'sent_audited',s.eventDbKey+':sent',{purpose:'slack-action-succeeded',recordId:s.recordId,cycleId:s.cycleId,eventKey:s.eventKey,taskId:s.taskId,sentAt:s.sentAt,attemptId:s.attemptId,claimExecutionId:s.claimExecutionId});
   case 'sent_audited':return at(s,'complete_campaign','GET',CAM+s.recordId);
   case 'complete_campaign':
    record(s,r);if(String(s.fields[F.cycle]||'initial')!==s.cycleId)throw Error('Campaign cycle changed outside the coordinator while its mutex was held. Preserve the sent receipt and reconcile.');
    return at(s,'sent_mirrored','PATCH',CAM+s.recordId,{fields:{[F.delivery]:JSON.stringify(delivery(s,'pending'))}});
   case 'sent_mirrored':record(s,r);return at(s,'complete_task','GET',TASK+'/'+s.taskId);
   case 'complete_task':{
    if(r.id!==s.taskId||r.fields?.['Automation Key']!==s.eventKey)throw Error('Completion task identity mismatch.');
    // Do not erase owner/listener work that already changed this task after the Slack event.
    if(r.fields.Status==='Blocked'&&String(r.fields.Notes||'').startsWith('PENDING ALERT DELIVERY. '+s.eventKey))return at(s,'task_completed','PATCH',TASK+'/'+s.taskId,{fields:{Status:'Not Started',Notes:'SLACK ACTION SUCCEEDED. '+s.eventKey+'\nDelivered '+s.sentAt+'. Replenishment queue warning, not the final send date. Any forecast due date is an earliest queue-depletion bound at configured capacity, not an exact normal-volume-drop prediction.'}});
    return insert(s,'downstream_claimed',s.eventDbKey+':downstream_claim',{purpose:'downstream-request-claim',recordId:s.recordId,cycleId:s.cycleId,claimedAt:new Date().toISOString()});
   }
   case 'task_completed':return insert(s,'downstream_claimed',s.eventDbKey+':downstream_claim',{purpose:'downstream-request-claim',recordId:s.recordId,cycleId:s.cycleId,claimedAt:new Date().toISOString()});
   case 'downstream_claimed':
    s.sendDownstream=!!r.inserted;return release(s,'downstream',{ok:true,slackSent:true});
   case 'released':
    if(!r.released&&!r.already_released)throw Error('Mutex release is unconfirmed.');s.lockOwned=false;
    if(s.afterRelease==='downstream'&&s.sendDownstream){s.stage='downstream_called';return result(s,null,'downstream',{request:{body:{recordId:s.recordId,cycleId:s.cycleId}}});}
    return finish(s,s.finishPayload,s.finishPayload?.ok===false?409:200);
   case 'downstream_called':
    // An immutable acceptance record is stored without acquiring another campaign mutex.
    // It does not rewrite mutable campaign metadata, and it never claims execution completion.
    return pg(s,'downstream_audited','pg_append',[s.eventDbKey+':downstream_accepted',s.resource,s.claimExecutionId,JSON.stringify({purpose:'downstream-http-accepted',recordId:s.recordId,cycleId:s.cycleId,acceptedAt:new Date().toISOString()})]);
   case 'downstream_audited':return finish(s,{ok:true,slackSent:true,downstream:'accepted'});
   default:throw Error('Unexpected coordinator stage.');
  }
 }catch(e){return failure(s,e);}
}

return [{json:plan($input.first().json)}];
